package com.turboio.addon;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.zip.*;

public final class LifelogAudioExportTest {
 static int checks;static final String A=repeat('a',64),B=repeat('b',64),P=repeat('c',64),C=repeat('d',32);static final byte[] SILENCE={(byte)0xf8,(byte)0xff,(byte)0xfe};static final LifelogAudioArchive.Guard OK=()->{};
 static String repeat(char c,int count){char[] s=new char[count];Arrays.fill(s,c);return new String(s);}static void yes(boolean b){checks++;if(!b)throw new AssertionError("check "+checks);}interface Operation{void run()throws Exception;}static void reject(String code,Operation run)throws Exception{try{run.run();throw new AssertionError("expected "+code);}catch(IOException e){yes(code.equals(e.getMessage()));}}
 static void var(ByteArrayOutputStream b,int n){while(n>127){b.write((n&127)|128);n>>>=7;}b.write(n);}static byte[] wire(String message,byte[] payload){ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(8);out.write(1);out.write(16);var(out,0xa3);out.write(26);byte[] json=message.getBytes(java.nio.charset.StandardCharsets.UTF_8);var(out,json.length);out.write(json,0,json.length);out.write(34);var(out,payload.length);out.write(payload,0,payload.length);return out.toByteArray();}
 static Map<String,Object> status(long batches){return WireJson.object("phase","STOPPED","saved_batches",batches,"rejected_batches",0,"unconfirmed_batches",0,"error","");}
 public static void main(String[] args)throws Exception{
  File root=new File(args[0]),files=new File(root,"files"),cache=new File(root,"cache");yes(files.mkdir()&&cache.mkdir());String task="task-current",material=LifelogAudioLibrary.material(A,task);List<Object> sessions;
  try(LifelogAudioLibrary library=new LifelogAudioLibrary(files,A,OK)){library.start(C,P,1,task,1000);library.update(C,status(2),2000);yes(!Boolean.TRUE.equals(WireJson.map(library.selected(material).get(0)).get("source_link_verified")));library.associate(new HashSet<>(Arrays.asList("other-task")),2100);yes(!Boolean.TRUE.equals(WireJson.map(library.selected(material).get(0)).get("source_link_verified")));library.associate(new HashSet<>(Arrays.asList(task)),2200);sessions=library.selected(material);yes(Boolean.TRUE.equals(WireJson.map(sessions.get(0)).get("source_link_verified")));library.associate(Collections.emptySet(),2300);yes(Boolean.TRUE.equals(WireJson.map(library.selected(material).get(0)).get("source_link_verified")));}
  try(LifelogAudioLibrary other=new LifelogAudioLibrary(files,B,OK)){yes(other.selected(material).isEmpty());other.start(repeat('e',32),P,1,task,1000);other.associate(Collections.singleton(task),1100);yes(other.selected(material).isEmpty());}
  String message="{\"taskId\":\"task-current\",\"vpu\":0,\"vad\":1}";byte[] wire=wire(message,SILENCE);AtomicBoolean admit=new AtomicBoolean(true);List<Object> archives;
  LifelogAudioCollector collector=LifelogAudioCollector.open(files,A,P,1,C,LifelogAudioManager.Limits.standard(),LifelogAudioCollector.Limits.standard(),(p,g)->admit.get(),OK);
  yes(collector.offer(P,1,"A3",message,wire,1200,100000000)==LifelogAudioCollector.Offer.QUEUED);yes(collector.offer(P,1,"A3",message,wire,1300,200000000)==LifelogAudioCollector.Offer.QUEUED);archives=collector.checkpoint().get(5,TimeUnit.SECONDS);yes(archives.size()==1&&"sealed".equals(WireJson.map(archives.get(0)).get("phase")));yes(((Number)WireJson.map(archives.get(0)).get("count")).longValue()==2);yes(((Number)collector.snapshot().get("saved_batches")).longValue()==2);
  Map<String,Object> first=WireJson.map(archives.get(0));File raw=new File(files,"lifelog-audio/"+A+"/"+first.get("stream")+"/original.frames");String initial=LifelogAudioExport.sha(raw);yes(collector.offer(P,1,"A3",message,wire,1400,300000000)==LifelogAudioCollector.Offer.QUEUED);Map<String,Object> terminal=collector.stop("capture_stopped").get(5,TimeUnit.SECONDS);yes(((Number)terminal.get("saved_batches")).longValue()==3);yes(initial.equals(LifelogAudioExport.sha(raw)));rejectFuture(collector.checkpoint());
  AtomicInteger decoded=new AtomicInteger(),closed=new AtomicInteger();LifelogAudioExport.Decoders decoders=()->new LifelogAudioExport.Decoder(){public void validate(byte[] packet,int samples)throws IOException{yes(Arrays.equals(packet,SILENCE)&&samples==960);decoded.incrementAndGet();}public void close(){closed.incrementAndGet();}};
  LifelogAudioExport.Draft draft=LifelogAudioExport.prepare(files,cache,A,material,sessions,archives,decoders,OK,10000);yes(draft.frames==2&&draft.samples==1920&&draft.parts==1&&decoded.get()==2&&closed.get()==1);yes(initial.equals(LifelogAudioExport.sha(raw)));ByteArrayOutputStream exported=new ByteArrayOutputStream();LifelogAudioExport.copy(draft,exported,OK);yes(exported.size()==draft.size);try(ZipFile zip=new ZipFile(draft.file)){yes(zip.size()==3&&zip.getEntry("说明.txt")!=null);try(InputStream in=zip.getInputStream(zip.getEntry("片段-001.opus"))){Files.copy(in,new File(root,"verified-synthetic.opus").toPath());}String note=new String(zip.getInputStream(zip.getEntry("说明.txt")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);yes(note.contains("不代表完整全天录音"));}
  yes(LifelogAudioExport.load(cache,draft.id,A,10001).frames==2);reject("AUDIO_EXPORT_DRAFT",()->LifelogAudioExport.load(cache,draft.id,B,10001));reject("AUDIO_EXPORT_DRAFT",()->LifelogAudioExport.load(cache,draft.id,A,10000+LifelogAudioExport.TTL+1));
  reject("AUDIO_EXPORT_SOURCE_PENDING",()->LifelogAudioExport.prepare(files,cache,A,material,Collections.emptyList(),archives,decoders,OK,10001));reject("AUDIO_EXPORT_CONTEXT",()->LifelogAudioExport.prepare(files,cache,"wrong",material,sessions,archives,decoders,OK,10001));
  reject("OFFICIAL_ACCOUNT_CHANGED",()->LifelogAudioExport.copy(draft,new ByteArrayOutputStream(),()->{throw new IOException("OFFICIAL_ACCOUNT_CHANGED");}));
  byte[] damaged=Files.readAllBytes(raw.toPath());damaged[damaged.length-1]^=1;Files.write(raw.toPath(),damaged);reject("AUDIO_ARCHIVE_COMMITTED_CORRUPT",()->LifelogAudioExport.prepare(files,cache,A,material,sessions,archives,decoders,OK,10001));yes(new File(cache,"lifelog-audio-exports").list().length==1);
  byte[] bad=Files.readAllBytes(draft.file.toPath());bad[50]^=1;Files.write(draft.file.toPath(),bad);reject("AUDIO_EXPORT_CHANGED",()->LifelogAudioExport.copy(draft,new ByteArrayOutputStream(),OK));LifelogAudioExport.remove(cache,draft.id);yes(new File(cache,"lifelog-audio-exports").list().length==0);
  ByteArrayOutputStream ogg=new ByteArrayOutputStream();OpusFile mux=new OpusFile(ogg,1234);byte[] padded=new byte[255];padded[0]=(byte)0xf8;mux.packet(padded);yes(mux.finish()==960);byte[] page=ogg.toByteArray();yes(page[0]=='O');reject("AUDIO_OPUS_PACKET_DURATION",()->OpusFile.samples48(new byte[]{3,0}));reject("AUDIO_OPUS_CHANNEL_UNSUPPORTED",()->OpusFile.samples48(new byte[]{4}));
  System.out.println("Lifelog audio export: "+checks+" checks passed; synthetic only");
 }
 static void rejectFuture(CompletableFuture<?> f)throws Exception{try{f.get(5,TimeUnit.SECONDS);throw new AssertionError("checkpoint after stop");}catch(ExecutionException e){yes("AUDIO_CHECKPOINT_BUSY".equals(e.getCause().getMessage()));}}
}
